  1	/**
  2	 * OpenAI Codex in-sandbox runner.
  3	 *
  4	 * This file is shipped INTO the sandbox by the orchestrator and executed there as
  5	 * `node __agent_eval__/run.mjs '<AgentRunInput JSON>'`. It is intentionally
  6	 * ZERO-DEPENDENCY (only `node:*` builtins) because the sandbox only has the
  7	 * fixture's own deps + the installed `codex` CLI — it cannot import anything from
  8	 * the @vercel/agent-eval package.
  9	 *
 10	 * Dual mode:
 11	 *   - runnable: invoked directly → reads argv, runs the agent, writes the result
 12	 *     file + prints a status line, exits 0.
 13	 *   - importable: `import { runAgent } from './run.mjs'` → returns a RunnerResult
 14	 *     (no file write, no exit). This is what a future in-sandbox judge reuses.
 15	 *
 16	 * The pure helpers below are exported (not just `runAgent`) so they can be
 17	 * unit-tested directly — the same code the sandbox runs (see codex.test.ts).
 18	 *
 19	 * SECRETS: the apiKey is NOT in the AgentRunInput JSON. It arrives via process.env
 20	 * (AI_GATEWAY_API_KEY for the gateway, else OPENAI_API_KEY for direct OpenAI) and
 21	 * is piped into `codex login --with-api-key` over stdin — never on the argv.
 22	 */
 23	
 24	import { spawnSync } from 'node:child_process';
 25	import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
 26	import { homedir } from 'node:os';
 27	import { dirname, join } from 'node:path';
 28	import { fileURLToPath } from 'node:url';
 29	
 30	/**
 31	 * Extract transcript from Codex JSON output.
 32	 * When run with --json, Codex outputs JSONL to stdout with the full transcript.
 33	 * Preserved verbatim from the old adapter.
 34	 *
 35	 * @param {string} output
 36	 * @returns {string|undefined}
 37	 */
 38	export function extractTranscriptFromOutput(output) {
 39	  if (!output || !output.trim()) {
 40	    return undefined;
 41	  }
 42	
 43	  // The --json output is already the transcript in JSONL format.
 44	  // Filter to only include lines that look like JSON objects.
 45	  const lines = output.split('\n').filter((line) => {
 46	    const trimmed = line.trim();
 47	    return trimmed.startsWith('{') && trimmed.endsWith('}');
 48	  });
 49	
 50	  if (lines.length === 0) {
 51	    return undefined;
 52	  }
 53	
 54	  return lines.join('\n');
 55	}
 56	
 57	/**
 58	 * Find the `thread.started` event's thread_id in Codex JSON stdout.
 59	 * Preserved verbatim from the old adapter. Non-JSON lines are ignored.
 60	 *
 61	 * @param {string} output
 62	 * @returns {string|undefined}
 63	 */
 64	export function extractCodexThreadId(output) {
 65	  for (const line of output.split('\n')) {
 66	    if (!line.trim()) continue;
 67	    try {
 68	      const event = JSON.parse(line);
 69	      if (event.type === 'thread.started' && typeof event.thread_id === 'string') {
 70	        return event.thread_id;
 71	      }
 72	    } catch {
 73	      // Ignore non-JSON output lines.
 74	    }
 75	  }
 76	
 77	  return undefined;
 78	}
 79	
 80	/**
 81	 * Scan a Codex session transcript (JSONL) for the last `turn_context` model seen.
 82	 * Preserved verbatim from the old adapter. Non-JSON lines are ignored.
 83	 *
 84	 * @param {string|undefined} transcript
 85	 * @returns {string|undefined}
 86	 */
 87	export function extractObservedModelFromCodexSession(transcript) {
 88	  if (!transcript) return undefined;
 89	
 90	  let observedModel;
 91	  for (const line of transcript.split('\n')) {
 92	    if (!line.trim()) continue;
 93	    try {
 94	      const event = JSON.parse(line);
 95	      const model = event.payload?.model ?? event.payload?.collaboration_mode?.settings?.model;
 96	      if (event.type === 'turn_context' && typeof model === 'string') {
 97	        observedModel = model;
 98	      }
 99	    } catch {
100	      // Ignore non-JSON transcript lines.
101	    }
102	  }
103	
104	  return observedModel;
105	}
106	
107	/**
108	 * Recursively collect every `*.jsonl` file path under `~/.codex/sessions`.
109	 * The old adapter used `find ~/.codex/sessions -type f -name '*.jsonl'`.
110	 *
111	 * @param {string} dir
112	 * @returns {string[]} absolute paths
113	 */
114	function listSessionFiles(dir) {
115	  const out = [];
116	  let entries;
117	  try {
118	    entries = readdirSync(dir, { withFileTypes: true });
119	  } catch {
120	    return out;
121	  }
122	  for (const entry of entries) {
123	    const full = join(dir, entry.name);
124	    if (entry.isDirectory()) {
125	      out.push(...listSessionFiles(full));
126	    } else if (entry.isFile() && entry.name.endsWith('.jsonl')) {
127	      out.push(full);
128	    }
129	  }
130	  return out;
131	}
132	
133	/**
134	 * Locate + read the Codex session transcript file.
135	 *
136	 * Codex writes JSONL session files under `~/.codex/sessions`. The old adapter, in
137	 * shell, did:
138	 *   - with a threadId: `find ... -name '*<threadId>*.jsonl' | head -1`
139	 *   - without:         `find ... -name '*.jsonl' | sort | tail -1`
140	 *
141	 * We mirror that exactly: filter by threadId substring when present (first match),
142	 * otherwise lexicographically sort all `.jsonl` paths and take the last. Codex
143	 * session filenames are timestamp-prefixed, so the lexicographic max is the newest.
144	 *
145	 * Best-effort: any failure → undefined (never throws).
146	 *
147	 * @param {string|undefined} threadId
148	 * @returns {string|undefined}
149	 */
150	function captureCodexSessionTranscript(threadId) {
151	  try {
152	    const sessionsDir = join(homedir(), '.codex', 'sessions');
153	    const files = listSessionFiles(sessionsDir);
154	    if (files.length === 0) return undefined;
155	
156	    let chosen;
157	    if (threadId) {
158	      // `find ... | head -1`: the first match in the traversal order.
159	      chosen = files.find((f) => f.includes(threadId));
160	    } else {
161	      // `find ... | sort | tail -1`: lexicographic max.
162	      chosen = files.slice().sort()[files.length - 1];
163	    }
164	    if (!chosen) return undefined;
165	    return readFileSync(chosen, 'utf8');
166	  } catch {
167	    return undefined;
168	  }
169	}
170	
171	/**
172	 * Build the `codex login --with-api-key` arg list. The key itself is piped over
173	 * stdin (spawnSync { input }), never placed on the argv.
174	 *
175	 * @returns {string[]}
176	 */
177	export function buildCodexLoginArgs() {
178	  return ['login', '--with-api-key'];
179	}
180	
181	/**
182	 * Build the `codex exec` arg list, reproducing the old shell command verbatim:
183	 *   codex exec --profile default[ --model <m>] --dangerously-bypass-approvals-and-sandbox
184	 *     --json --skip-git-repo-check[ -c model_reasoning_effort="<e>"]
185	 *     [ -c model_verbosity="<v>"] '<prompt>'
186	 *
187	 * The model / reasoningEffort / verbosity values are HOST-computed (from
188	 * parseModelString) and arrive via input.extra so they match the TOML profile.
189	 *
190	 * Note: with spawnSync (argv, not a shell), the `-c key="value"` tokens keep their
191	 * literal quotes exactly as the old shell string had them, and the prompt is a
192	 * plain argv element (no shell escaping needed).
193	 *
194	 * @param {{prompt:string, extra?:Record<string,unknown>}} input
195	 * @returns {string[]}
196	 */
197	export function buildCodexExecArgs(input) {
198	  const extra = input.extra ?? {};
199	  const cliModel = extra.cliModel ?? null;
200	  const reasoningEffort = extra.reasoningEffort ?? null;
201	  const verbosity = extra.verbosity ?? null;
202	
203	  const args = ['exec', '--profile', 'default'];
204	  if (cliModel) {
205	    args.push('--model', String(cliModel));
206	  }
207	  args.push('--dangerously-bypass-approvals-and-sandbox', '--json', '--skip-git-repo-check');
208	  if (reasoningEffort) {
209	    args.push('-c', `model_reasoning_effort="${reasoningEffort}"`);
210	  }
211	  if (verbosity) {
212	    args.push('-c', `model_verbosity="${verbosity}"`);
213	  }
214	  args.push(input.prompt);
215	  return args;
216	}
217	
218	/**
219	 * Run Codex over the workspace at `input.cwd` and return a RunnerResult.
220	 *
221	 * Two-step, mirroring the old adapter's `codex login --with-api-key && codex exec`:
222	 *   1. `codex login --with-api-key` with the key piped on stdin. If login exits
223	 *      non-zero, short-circuit with ok:false WITHOUT running exec (the old `&&`).
224	 *   2. `codex exec ...` — capture transcript + observedModel even on non-zero exit.
225	 *
226	 * Auth env (AI_GATEWAY_API_KEY / OPENAI_API_KEY) arrives via process.env — the
227	 * orchestrator sets it on the `node run.mjs` invocation, and we pass process.env
228	 * straight through to the CLI. The login key is read from that same env.
229	 *
230	 * @param {import('../plugin/contract.js').AgentRunInput} input
231	 * @returns {Promise<import('../plugin/contract.js').RunnerResult>}
232	 */
233	export async function runAgent(input) {
234	  // The login key: gateway runs use AI_GATEWAY_API_KEY; direct OpenAI uses
235	  // OPENAI_API_KEY. Reading both (gateway first) keeps the runner agnostic to the
236	  // mode while never carrying the secret in the argv JSON.
237	  const apiKey = process.env.AI_GATEWAY_API_KEY || process.env.OPENAI_API_KEY || '';
238	
239	  // Step 1: codex login --with-api-key (key piped on stdin). The built-in openai
240	  // provider requires bearer auth; the gateway provider reads env_key but login is
241	  // harmless/consistent there too. This is the left side of the old `&&`.
242	  const login = spawnSync('codex', buildCodexLoginArgs(), {
243	    cwd: input.cwd,
244	    env: process.env,
245	    input: apiKey,
246	    encoding: 'utf8',
247	    maxBuffer: 64 * 1024 * 1024,
248	  });
249	
250	  const loginStdout = login.stdout || '';
251	  const loginStderr = login.stderr || '';
252	  const loginExit = login.status == null ? -1 : login.status;
253	
254	  if (login.error || loginExit !== 0) {
255	    // Short-circuit: the old `codex login ... && codex exec ...` never ran exec
256	    // when login failed. Surface the same kind of error (last 5 lines, else coded
257	    // fallback) over the login output.
258	    const loginOutput = loginStdout + loginStderr;
259	    const errorLines = loginOutput.trim().split('\n').slice(-5).join('\n');
260	    const fallback = login.error
261	      ? `Failed to run codex: ${login.error.message}`
262	      : `Codex CLI exited with code ${loginExit}`;
263	    return {
264	      ok: false,
265	      output: loginOutput,
266	      transcript: null,
267	      observedModel: null,
268	      error: errorLines || fallback,
269	      agentExitCode: loginExit,
270	    };
271	  }
272	
273	  // Step 2: codex exec. Blocking is fine — the runner has nothing else to do while
274	  // the agent works. The sandbox-level timeout bounds it.
275	  const res = spawnSync('codex', buildCodexExecArgs(input), {
276	    cwd: input.cwd,
277	    env: process.env,
278	    encoding: 'utf8',
279	    maxBuffer: 64 * 1024 * 1024,
280	  });
281	
282	  const stdout = res.stdout || '';
283	  const stderr = res.stderr || '';
284	  // Preserve the old concatenation order: stdout THEN stderr.
285	  const output = stdout + stderr;
286	  // spawnSync sets status=null + error when the binary can't be spawned at all.
287	  const agentExitCode = res.status == null ? -1 : res.status;
288	
289	  // Capture transcript + observed model regardless of success (the old adapter did
290	  // this even on the non-zero-exit path). The inline --json on stdout is the
291	  // transcript; observedModel comes from the saved session file under ~/.codex.
292	  const transcript = extractTranscriptFromOutput(output) ?? null;
293	  const threadId = extractCodexThreadId(output);
294	  const sessionTranscript = captureCodexSessionTranscript(threadId);
295	  const observedModel = extractObservedModelFromCodexSession(sessionTranscript) ?? null;
296	
297	  if (res.error || agentExitCode !== 0) {
298	    // Mirror the old error string: last 5 lines of output, else a coded fallback.
299	    const errorLines = output.trim().split('\n').slice(-5).join('\n');
300	    const fallback = res.error
301	      ? `Failed to run codex: ${res.error.message}`
302	      : `Codex CLI exited with code ${agentExitCode}`;
303	    return {
304	      ok: false,
305	      output,
306	      transcript,
307	      observedModel,
308	      error: errorLines || fallback,
309	      agentExitCode,
310	    };
311	  }
312	
313	  return { ok: true, output, transcript, observedModel, error: null, agentExitCode };
314	}
315	
316	/* ─────────────────────────── runnable (CLI) entry ─────────────────────────── */
317	
318	// True when this file is executed directly (`node run.mjs ...`), false when imported.
319	const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
320	
